select cpr.id, cpr.display_owner AS owner, cpr.display_no AS no, cpr.display_name AS name, cpr.display_contract_id AS contract_id, cpr.payment_plan_id, cpr.approval_status, cpr.effective_version_id, cpr.pending_version_id, cpr.display_record_amount AS record_amount, cpr.display_total_loan_amount AS total_loan_amount, cpr.display_total_cost_amount AS total_cost_amount, cpr.display_total_misc_fee_amount AS total_misc_fee_amount, cpr.display_total_commission_amount AS total_commission_amount, cpr.display_total_revenue_amount AS total_revenue_amount, cpr.display_record_end_time AS record_end_time, cpr.display_first_loan_time AS first_loan_time, cpr.display_last_loan_time AS last_loan_time, cpr.display_first_repayment_time AS first_repayment_time, cpr.display_last_repayment_time AS last_repayment_time, cpr.lock_version, cpr.create_time, cpr.update_time, cpr.create_user, cpr.update_user, cpr.organization_id, ifnull(c.name, '') as contractName from ( select base_record.*, display_version.value_snapshot AS display_value_snapshot, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.name')), base_record.name) AS display_name, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.no')), base_record.no) AS display_no, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.contractId')), base_record.contract_id) AS display_contract_id, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.owner')), base_record.owner) AS display_owner, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.recordAmount') + 0, base_record.record_amount) AS display_record_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.totalLoanAmount') + 0, base_record.total_loan_amount) AS display_total_loan_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.totalCostAmount') + 0, base_record.total_cost_amount) AS display_total_cost_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.totalMiscFeeAmount') + 0, base_record.total_misc_fee_amount) AS display_total_misc_fee_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.totalCommissionAmount') + 0, base_record.total_commission_amount) AS display_total_commission_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.totalRevenueAmount') + 0, base_record.total_revenue_amount) AS display_total_revenue_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.firstLoanTime') + 0, base_record.first_loan_time) AS display_first_loan_time, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.lastLoanTime') + 0, base_record.last_loan_time) AS display_last_loan_time, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.firstRepaymentTime') + 0, base_record.first_repayment_time) AS display_first_repayment_time, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.lastRepaymentTime') + 0, base_record.last_repayment_time) AS display_last_repayment_time, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.firstRepaymentTime') + 0, base_record.record_end_time) AS display_record_end_time from contract_payment_record base_record left join contract_payment_record_version display_version on display_version.id = COALESCE( base_record.pending_version_id, case when base_record.effective_version_id is null then ( select latest_version.id from contract_payment_record_version latest_version where latest_version.payment_record_id = base_record.id order by latest_version.version_no desc limit 1 ) end ) ) cpr left join contract c on c.id = cpr.display_contract_id
join sys_organization_user sou on cpr.owner = sou.user_id and ( sou.department_id in
#{deptId}
or sou.user_id = #{currentUser}
)
where cpr.organization_id = #{currentOrg}
and cpr.owner = #{currentUser}
and cpr.contract_id = #{request.contractId}
and c.customer_id = #{request.customerId}
and cpr.display_name like concat('%', #{request.keyword},'%')

select cpr.id, cpr.owner, cpr.no, cpr.name, cpr.contract_id, cpr.payment_plan_id, cpr.approval_status, cpr.effective_version_id, cpr.pending_version_id, cpr.record_amount, cpr.total_loan_amount, cpr.total_cost_amount, cpr.total_misc_fee_amount, cpr.total_commission_amount, cpr.total_revenue_amount, cpr.record_end_time, cpr.first_loan_time, cpr.last_loan_time, cpr.first_repayment_time, cpr.last_repayment_time, cpr.lock_version, cpr.create_time, cpr.update_time, cpr.create_user, cpr.update_user, cpr.organization_id, c.name as contractName from contract_payment_record cpr join contract c on c.id = cpr.contract_id
join sys_organization_user sou on cpr.owner = sou.user_id and ( sou.department_id in
#{deptId}
)
where cpr.organization_id = #{currentOrg} and cpr.id in
#{id}
and cpr.owner = #{currentUser}

select
    ifnull(sum(c.amount), 0) as totalAmount,
    ifnull(sum(cpr_sum.receivedAmount), 0) as receivedAmount,
    ifnull((sum(c.amount) - sum(cpr_sum.receivedAmount)), 0) as pendingAmount
from contract c
left join (
    select cpr.contract_id, sum(cpr.record_amount) as receivedAmount
    from contract_payment_record cpr

        join sys_organization_user sou on cpr.owner = sou.user_id
        and (
        sou.department_id in

            #{deptId}

        )

    where cpr.organization_id = #{orgId}

        and cpr.owner = #{userId}

    group by contract_id
) cpr_sum on c.id = cpr_sum.contract_id

where c.organization_id = #{orgId}
and c.customer_id = #{customerId}

foreach.if:
left join JSON_TABLE(
    COALESCE(JSON_EXTRACT(cpr.display_value_snapshot, '$.moduleFields'), JSON_ARRAY()),
    '$[*]' COLUMNS(
        field_id VARCHAR(255) PATH '$.fieldId',
        field_value VARCHAR(4000) PATH '$.fieldValue' NULL ON EMPTY
    )
) ${tablePrefix}_version_${i}
on ${tablePrefix}_version_${i}.field_id = #{condition.name}

    left join contract_payment_record_field_blob ${tablePrefix}_${i}
    on cpr.id = ${tablePrefix}_${i}.resource_id and ${tablePrefix}_${i}.field_id = #{condition.name}


    left join contract_payment_record_field ${tablePrefix}_${i}
    on cpr.id = ${tablePrefix}_${i}.resource_id and ${tablePrefix}_${i}.field_id = #{condition.name}

choose.when:
left join contract_payment_record_field sort_table
on cpr.id = sort_table.resource_id and sort_table.field_id = #{sortName}
left join JSON_TABLE(
    COALESCE(JSON_EXTRACT(cpr.display_value_snapshot, '$.moduleFields'), JSON_ARRAY()),
    '$[*]' COLUMNS(
        field_id VARCHAR(255) PATH '$.fieldId',
        field_value VARCHAR(4000) PATH '$.fieldValue' NULL ON EMPTY
    )
) sort_version_table on sort_version_table.field_id = #{sortName}
left join sys_module_field module_table on module_table.id = #{sortName}

