SELECT sum(cpr.display_record_amount) as amount, sum(cpr.display_record_amount) / count(*) as averageAmount FROM ( select base_record.*, display_version.value_snapshot AS display_value_snapshot, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.name')), base_record.name) AS display_name, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.no')), base_record.no) AS display_no, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.contractId')), base_record.contract_id) AS display_contract_id, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.owner')), base_record.owner) AS display_owner, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.recordAmount') + 0, base_record.record_amount) AS display_record_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.firstRepaymentTime') + 0, base_record.record_end_time) AS display_record_end_time from contract_payment_record base_record left join contract_payment_record_version display_version on display_version.id = COALESCE( base_record.pending_version_id, case when base_record.effective_version_id is null then ( select latest_version.id from contract_payment_record_version latest_version where latest_version.payment_record_id = base_record.id order by latest_version.version_no desc limit 1 ) end ) ) cpr LEFT JOIN contract c on c.id = cpr.display_contract_id
join sys_organization_user on cpr.owner = sys_organization_user.user_id and ( sys_organization_user.department_id in
#{deptId}
or sys_organization_user.user_id = #{userId}
)
where cpr.organization_id = #{orgId}
and cpr.owner = #{userId}
and ( cpr.display_name like concat('%', #{request.keyword},'%') )

SELECT *
FROM contract_payment_record
WHERE id = #{id}
  AND organization_id = #{orgId}
FOR UPDATE

